{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS public.shipment_status_mapping ( SHIPPING_STATUS VARCHAR(256), Mapped_Status VARCHAR(256) ); DELETE FROM public.shipment_status_mapping; INSERT INTO public.shipment_status_mapping VALUES (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'), (\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'CONFIRMED\',\'Open\'), (\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'), (\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'), (\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'), (\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'), (\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'), (\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'), (\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'), (\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'), (\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'), (\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'), (\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'), (\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'), (\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'), (\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'), (\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'), (\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'), (\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'), (\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'), (\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'), (\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'), (\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); CREATE TABLE IF NOT EXISTS public.facility_pincode ( facility VARCHAR(256), pincode VARCHAR(20) ); CREATE TABLE IF NOT EXISTS public.Anveshan_UNICOMMERCE_FACT_ITEMS ( order_id VARCHAR(256), reference_code VARCHAR(256), sales_order_item_id VARCHAR(256), saleorderitemcode VARCHAR(256), product_id VARCHAR(256), productname VARCHAR(512), sku VARCHAR(256), master_sku VARCHAR(256), category VARCHAR(256), customer_name VARCHAR(512), email VARCHAR(512), contact_num VARCHAR(50), city VARCHAR(256), state VARCHAR(256), pincode VARCHAR(20), marketplace VARCHAR(256), shop_name VARCHAR(256), order_status VARCHAR(256), order_date TIMESTAMP, order_type VARCHAR(256), shipping_status VARCHAR(256), shipping_last_update_date TIMESTAMP, dispatch_date DATE, delivered_date DATE, manifest_date DATE, awb VARCHAR(256), courier VARCHAR(256), warehouse_name VARCHAR(256), facility VARCHAR(256), currency VARCHAR(10), selling_price NUMERIC(18,2), tax NUMERIC(18,2), discount NUMERIC(18,2), shipping_price NUMERIC(18,2), payment_mode VARCHAR(100), suborder_quantity INTEGER, return_flag INTEGER, invoice_date DATE, last_update_date TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ); CREATE TABLE IF NOT EXISTS public.Anveshan_EasyEcom_FACT_ITEMS ( reference_code VARCHAR(256), order_id VARCHAR(256), suborder_id VARCHAR(256), Marketplace_LineItem_ID VARCHAR(256), transactionid VARCHAR(256), product_id VARCHAR(256), productname VARCHAR(512), sku VARCHAR(256), master_sku VARCHAR(256), category VARCHAR(256), mapped_category VARCHAR(256), mapped_sub_category VARCHAR(256), mapped_product_name VARCHAR(512), commonsku VARCHAR(256), Gender VARCHAR(50), Color_Family VARCHAR(100), Product_Type VARCHAR(256), Product_Variant VARCHAR(256), FitType VARCHAR(100), Sleeve_Type VARCHAR(100), Neck_Collar_Type VARCHAR(100), Size VARCHAR(50), categoryType VARCHAR(256), Garment_Length VARCHAR(100), customer_name VARCHAR(512), email VARCHAR(512), contact_num VARCHAR(50), city VARCHAR(256), state VARCHAR(256), pincode VARCHAR(20), pickup_pincode VARCHAR(20), marketplace VARCHAR(256), shop_name VARCHAR(256), order_status VARCHAR(256), order_date TIMESTAMP, order_type VARCHAR(256), new_customer_flag INTEGER, shipping_status VARCHAR(256), shipping_last_update_date TIMESTAMP, manifest_date DATE, delivered_date DATE, awb VARCHAR(256), courier VARCHAR(256), Days_in_shipment INTEGER, warehouse_name VARCHAR(256), currency VARCHAR(10), selling_price NUMERIC(18,2), tax NUMERIC(18,2), discount NUMERIC(18,2), shipping_price NUMERIC(18,2), payment_mode VARCHAR(100), suborder_quantity INTEGER, is_refund INTEGER, invoice_date DATE, last_update_date TIMESTAMP, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ); drop TABLE if exists public.anveshan_swiggy_sales_consolidated; CREATE TABLE public.anveshan_swiggy_sales_consolidated AS SELECT NULL::VARCHAR(256) AS customer_id, \'SWIGGY\' AS SHOP_NAME, \'SWIGGY\' AS marketplace, \'SWIGGY\' AS CHANNEL, \'SWIGGY\' AS SOURCE, ORDER_ID, order_id AS reference_code, NULL::VARCHAR(256) AS tags, NULL::VARCHAR(20) AS PHONE, NULL::VARCHAR(256) AS NAME, NULL::VARCHAR(256) AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, item_code AS SKU, item_code AS PRODUCT_ID, UPPER(Product_Name) AS PRODUCT_NAME, \'INR\' AS CURRENCY, UPPER(city) AS CITY, NULL::VARCHAR(256) AS State, \'DELIVERED\' AS ORDER_STATUS, CAST(Order_Date AS DATE) AS Order_Date, CAST(Order_Date AS TIMESTAMP) AS Order_Time, QUANTITY, selling_price_final AS GROSS_SALES_BEFORE_TAX, NULL::DECIMAL AS DISCOUNT, NULL::DECIMAL AS TAX, NULL::DECIMAL AS SHIPPING_PRICE, selling_price_final AS SELLING_PRICE, \'DELIVERED\' AS OMS_order_status, \'DELIVERED\' AS SHIPPING_STATUS, \'DELIVERED\' AS FINAL_SHIPPING_STATUS, order_id AS SALEORDERITEMCODE, order_id AS SALES_ORDER_ITEM_ID, NULL::VARCHAR(256) AS AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, NULL::VARCHAR(256) AS payment_mode, NULL::VARCHAR(256) AS COURIER, NULL::DATE AS DISPATCH_DATE, NULL::DATE AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, NULL::BIGINT AS RETURN_FLAG, NULL::BIGINT AS returned_quantity, NULL::DECIMAL AS returned_sales, NULL::BIGINT AS cancelled_quantity, NULL::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS acquisition_product, NULL::BIGINT AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, item_code AS SKU_CODE, UPPER(PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, commonsku, NULL::VARCHAR(256) AS WAREHOUSE, NULL::VARCHAR(10) AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, \'B2C\' AS Order_Type, NULL::DATE AS invoice_date, NULL::VARCHAR(20) AS week_type, NULL::DATE AS refund_date_final, NULL::DECIMAL AS refund_value, NULL::TIMESTAMP AS cancelled_at FROM public.anveshan_swiggy_sales_fact_items; drop table if exists public.Anveshan_sales_consolidated_intermediate_temp; CREATE TABLE public.Anveshan_sales_consolidated_intermediate_temp AS SELECT CAST(b.customer_id AS VARCHAR(256)) AS customer_id, UPPER(b.SHOP_NAME) AS SHOP_NAME, UPPER(b.marketplace) AS marketplace, UPPER(COALESCE(GA4.CHANNEL, b.FINAL_UTM_CHANNEL)) AS CHANNEL, UPPER(COALESCE(GA4.final_source, b.FINAL_UTM_SOURCE)) AS SOURCE, b.ORDER_ID, b.order_name AS reference_code, b.tags, b.PHONE, b.NAME, b.EMAIL, COALESCE( CAST(b.shipping_status_update_date AS TIMESTAMP), CAST(c.shipping_last_update_date AS TIMESTAMP), CAST(d.shipping_last_update_date AS TIMESTAMP) ) AS SHIPPING_LAST_UPDATE_DATE, b.SKU, b.PRODUCT_ID, UPPER(COALESCE(c.productname, b.PRODUCT_NAME)) AS PRODUCT_NAME, b.CURRENCY, UPPER(b.SHIPPING_CITY) AS CITY, UPPER(b.SHIPPING_STATE) AS State, UPPER(b.ORDER_STATUS) AS ORDER_STATUS, CAST(b.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(b.ORDER_TIMESTAMP AS TIMESTAMP) AS Order_Time, b.QUANTITY, b.GROSS_SALES_BEFORE_TAX, b.DISCOUNT_BEFORE_TAX AS DISCOUNT, b.TAX, b.SHIPPING_PRICE, b.TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(c.order_status, d.order_status)) AS OMS_order_status, UPPER(COALESCE(b.shipping_status, c.shipping_status, d.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) AS FINAL_SHIPPING_STATUS, CAST(b.LINE_ITEM_ID AS VARCHAR(256)) AS SALEORDERITEMCODE, d.sales_order_item_id AS SALES_ORDER_ITEM_ID, COALESCE(b.awb, c.awb, d.awb) AS AWB, b.GATEWAY AS PAYMENT_GATEWAY, CASE WHEN b.gateway ILIKE \'%cod%\' OR b.gateway ILIKE \'%cash on delivery%\' OR b.gateway ILIKE \'%cash_on_delivery%\' OR b.gateway ILIKE \'%cash%\' OR b.gateway ILIKE \'%manual%\' THEN \'COD\' WHEN b.gateway ILIKE \'%gokwik%\' OR b.gateway ILIKE \'%paytm%\' OR b.gateway ILIKE \'%razorpay%\' THEN \'Prepaid\' ELSE \'Manual\' END AS payment_mode, UPPER(COALESCE(c.Courier, d.courier, b.courier)) AS COURIER, COALESCE( CAST(b.Shipping_created_at AS DATE), CAST(c.manifest_date AS DATE), CAST(d.dispatch_date AS DATE) ) AS DISPATCH_DATE, COALESCE( CAST(c.delivered_date AS DATE), CAST(d.delivered_date AS DATE), CASE WHEN LOWER(b.shipping_status) = \'delivered\' THEN CAST(b.shipping_status_update_date AS DATE) END ) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, COALESCE( CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag ) AS RETURN_FLAG, CASE WHEN COALESCE( CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag ) = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN COALESCE(b.refund_quantity, 0) END AS returned_quantity, CASE WHEN COALESCE( CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag ) = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN COALESCE(b.refund_value, 0) END AS returned_sales, CASE WHEN LOWER(b.order_status) IN (\'cancelled\') THEN CAST(b.quantity AS BIGINT) END AS cancelled_quantity, b.shopify_new_customer_flag AS NEW_CUSTOMER_FLAG, UPPER(b.shopify_acquisition_product) AS acquisition_product, CAST(CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATEDIFF(day, CAST(COALESCE(b.shipping_status_update_date, c.shipping_last_update_date, d.shipping_last_update_date) AS DATE), CAST(b.ORDER_TIMESTAMP AS DATE)) WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATEDIFF(day, CAST(b.ORDER_TIMESTAMP AS DATE), CURRENT_DATE) END AS BIGINT) AS Days_in_Shipment, b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE, b.SKU_CODE, UPPER(COALESCE(b.PRODUCT_NAME_FINAL, c.productname)) AS PRODUCT_NAME_FINAL, UPPER(COALESCE(b.PRODUCT_CATEGORY, c.category)) AS PRODUCT_CATEGORY, COALESCE(CASE WHEN b.commonsku = \'\' THEN NULL ELSE b.commonsku END, c.master_sku) AS commonsku, UPPER(COALESCE(c.warehouse_name, d.warehouse_name)) AS WAREHOUSE, COALESCE(b.pincode, d.pincode, c.pincode) AS pincode, COALESCE(c.pickup_pincode, fa.pincode) AS source_pincode, UPPER(b.source_name) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, COALESCE(b.order_type, c.order_type) AS Order_Type, c.invoice_date, CASE WHEN DATEDIFF(day, CAST(b.ORDER_TIMESTAMP AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 0 AND 6 THEN \'T-7\' WHEN DATEDIFF(day, CAST(b.ORDER_TIMESTAMP AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 7 AND 29 THEN \'T-7-30\' WHEN DATEDIFF(day, CAST(b.ORDER_TIMESTAMP AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 30 AND 44 THEN \'T-7-30-15\' END AS week_type, b.refund_date_final, b.refund_value, b.cancelled_at FROM public.anweshan_shopify_fact_items b LEFT JOIN ( SELECT * FROM ( SELECT transactionid, final_source, channel, ROW_NUMBER() OVER (PARTITION BY transactionid ORDER BY 1) AS rn FROM public.anweshan_ga_order_by_source_consolidated ) x WHERE rn = 1 ) GA4 ON REPLACE(CAST(b.order_name AS VARCHAR), \'#\', \'\') = REPLACE(CAST(GA4.transactionid AS VARCHAR), \'#\', \'\') LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, Marketplace_LineItem_ID ORDER BY last_update_date DESC) AS rw FROM public.Anveshan_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%shopify%\' ) c ON REPLACE(CAST(b.order_name AS VARCHAR), \'#\', \'\') = REPLACE(CAST(c.reference_code AS VARCHAR), \'#\', \'\') AND REPLACE(CAST(b.LINE_ITEM_ID AS VARCHAR), \'`\', \'\') = REPLACE(CAST(c.Marketplace_LineItem_ID AS VARCHAR), \'`\', \'\') LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, SPLIT_PART(saleorderitemcode, \'-\', 1) ORDER BY shipping_last_update_date DESC) AS rw FROM public.Anveshan_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%shopify%\' ) d WHERE rw = 1 ) d ON b.order_id = d.order_id AND b.line_item_id = SPLIT_PART(d.saleorderitemcode, \'-\', 1) LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(facility) ORDER BY 1) AS rw FROM public.facility_pincode ) fa WHERE rw = 1 ) fa ON LOWER(d.warehouse_name) = LOWER(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, c.shipping_status, d.shipping_status, b.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) UNION ALL SELECT NULL::VARCHAR(256) AS customer_id, UPPER(SHOP_NAME) AS SHOP_NAME, UPPER(marketplace) AS marketplace, UPPER(marketplace) AS CHANNEL, UPPER(marketplace) AS SOURCE, ORDER_ID, reference_code, NULL::VARCHAR(256) AS tags, contact_num AS PHONE, customer_name AS NAME, email AS EMAIL, CAST(shipping_last_update_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, UPPER(PRODUCTNAME) AS PRODUCT_NAME, CURRENCY, UPPER(CITY) AS City, UPPER(STATE) AS State, UPPER(ORDER_STATUS) AS Order_Status, CAST(CAST(ORDER_DATE AS TIMESTAMP) AS DATE) AS Order_Date, CAST(ORDER_DATE AS TIMESTAMP) AS ORDER_TIMESTAMP, SUBORDER_QUANTITY AS QUANTITY, COALESCE(SELLING_PRICE, 0) - COALESCE(tax, 0) + COALESCE(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, UPPER(ORDER_STATUS) AS OMS_Order_Status, UPPER(b.Shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS, Marketplace_LineItem_ID AS SALEORDERITEMCODE, suborder_id AS SALES_ORDER_ITEM_ID, AWB, NULL::VARCHAR(256) AS Payment_Gateway, payment_mode AS Payment_Mode, UPPER(COURIER) AS COURIER, MANIFEST_DATE AS DISPATCH_DATE, DELIVERED_DATE, CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, IS_REFUND AS RETURN_FLAG, CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS BIGINT) END AS returned_quantity, CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN COALESCE(is_refund, 0) END AS returned_sales, CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS BIGINT) END AS cancelled_quantity, CAST(new_customer_flag AS VARCHAR(256)) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS ACQUISITION_PRODUCT, CAST(Days_in_shipment AS BIGINT) AS DAYS_IN_SHIPMENT, NULL::DATE AS ACQUISITION_DATE, SKU AS SKU_CODE, UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL, UPPER(mapped_category) AS PRODUCT_CATEGORY, COALESCE(CASE WHEN b.commonsku = \'\' THEN NULL ELSE b.commonsku END, b.master_SKU) AS commonsku, UPPER(WAREHOUSE_NAME) AS WAREHOUSE, pincode, pickup_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, b.order_type AS Order_Type, b.invoice_date, CASE WHEN DATEDIFF(day, CAST(ORDER_DATE AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 0 AND 6 THEN \'T-7\' WHEN DATEDIFF(day, CAST(ORDER_DATE AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 7 AND 29 THEN \'T-7-30\' WHEN DATEDIFF(day, CAST(ORDER_DATE AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 30 AND 44 THEN \'T-7-30-15\' END AS week_type, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at FROM public.Anveshan_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE NOT ( LOWER(marketplace) LIKE \'%shopify%\' OR LOWER(marketplace) LIKE \'%amazon%\' OR LOWER(marketplace) LIKE \'%gofynd%\' or lower(marketplace) like \'%flipkart%\' ) UNION ALL SELECT NULL::VARCHAR(256) AS customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, CASE WHEN afi.shop_name = \'Amazon_FBA_Saada\' THEN \'AMAZON_FBA\' ELSE \'AMAZON\' END AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL::VARCHAR(256) AS tags, NULL::VARCHAR(256) AS PHONE, afi.NAME, COALESCE(EEFI.EMAIL, UFI.EMAIL, AFI.EMAIL) AS EMAIL, COALESCE( CAST(EEFI.shipping_last_update_date AS TIMESTAMP), CAST(UFI.shipping_last_update_date AS TIMESTAMP) ) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, CAST(afi.PRODUCT_ID AS VARCHAR(256)) AS PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS TIMESTAMP) AS Order_Time, afi.QUANTITY, COALESCE(TOTAL_SALES, 0) - COALESCE(afi.tax, 0) + COALESCE(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(EEFI.order_status, UFI.order_status)) AS OMS_order_status, UPPER(COALESCE(EEFI.shipping_status, UFI.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, afi.ORDER_ID::VARCHAR || \'-\' || afi.PRODUCT_ID::VARCHAR AS SALEORDERITEMCODE, afi.ORDER_ID::VARCHAR || \'-\' || afi.PRODUCT_ID::VARCHAR AS SALES_ORDER_ITEM_ID, COALESCE(EEFI.awb, UFI.awb) AS AWB, NULL::VARCHAR(256) AS Payment_Gateway, UPPER(COALESCE(EEFI.payment_mode, UFI.payment_mode)) AS Payment_Mode, UPPER(COALESCE(EEFI.Courier, UFI.courier)) AS COURIER, COALESCE(EEFI.manifest_date, UFI.dispatch_date) AS DISPATCH_DATE, COALESCE(EEFI.delivered_date, UFI.delivered_date) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status, EEFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS BIGINT) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS BIGINT) END AS cancelled_quantity, NULL::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), CURRENT_DATE) WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), CURRENT_DATE) END AS Days_in_Shipment, NULL::DATE AS ACQUISITION_DATE, COALESCE(afi.SKU, UFI.PRODUCT_ID, EEFI.SKU) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(AFI.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, COALESCE(CASE WHEN AFI.commonsku = \'\' THEN NULL ELSE AFI.commonsku END, CAST(AFI.commonsku AS VARCHAR(256))) AS commonsku, UPPER(EEFI.WAREHOUSE_NAME) AS WAREHOUSE, CAST(eefi.pincode AS VARCHAR(20)) AS pincode, CAST(pickup_pincode AS VARCHAR(20)) AS pickup_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, afi.Order_Type, COALESCE(eefi.invoice_date) AS Invoice_Date, CASE WHEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 0 AND 6 THEN \'T-7\' WHEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 7 AND 29 THEN \'T-7-30\' WHEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 30 AND 44 THEN \'T-7-30-15\' END AS week_type, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at FROM public.anveshan_amazon_fact_items AFI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM public.Anveshan_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) EEFI ON AFI.Order_id = EEFI.reference_code AND AFI.SKU = EEFI.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM public.Anveshan_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON CAST(AFI.order_id AS VARCHAR(256)) = CAST(UFI.order_id AS VARCHAR(256)) AND CAST(AFI.product_id AS VARCHAR(256)) = CAST(UFI.PRODUCT_ID AS VARCHAR(256)) LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(facility) ORDER BY 1) AS rw FROM public.facility_pincode ) fa WHERE rw = 1 ) fa ON LOWER(ufi.warehouse_name) = LOWER(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) UNION ALL select cast(NULL AS varchar) customer_id, \'AMAZON VP\' AS Shop_name, \'AMAZON VP\' AS marketplace, \'AMAZON VP\' AS CHANNEL, \'AMAZON VP\' AS SOURCE, (Asin || startTime::varchar || endtime::varchar || OrderedUnits::varchar || shippedRevenue::varchar) as ORDER_ID, (Asin || startTime::varchar || endtime::varchar || OrderedUnits::varchar || shippedRevenue::varchar) AS reference_code, cast(null as varchar) tags, cast(NULL AS varchar) AS PHONE, cast(NULL AS varchar) as NAME, cast(NULL AS varchar) AS EMAIL, startTime::timestamp AS SHIPPING_LAST_UPDATE_DATE, asin as SKU, cast(asin as varchar) PRODUCT_ID, Product_Name_final as product_name, \'INR\' as CURRENCY, null AS CITY, NUll::varchar AS STATE, \'COMPLETED\' AS Order_Status, cast(startTime::timestamp as date) as Order_Date, CAST(startTime::timestamp AS datetime) Order_Time, shippedUnits as quantity, coalesce(shippedRevenue, 0) AS GROSS_SALES_BEFORE_TAX, cast(0 as double precision) AS DISCOUNT, cast(0 as double precision) as TAX, cast(0 as double precision) as SHIPPING_PRICE, shippedRevenue AS SELLING_PRICE, cast(null as varchar) AS OMS_order_status, \'COMPLETED\' AS SHIPPING_STATUS, \'COMPLETED\' AS FINAL_SHIPPING_STATUS, (Asin || startTime::varchar || endtime::varchar || shippedUnits::varchar || shippedRevenue::varchar) AS SALEORDERITEMCODE, (Asin || startTime::varchar || endtime::varchar || shippedUnits::varchar || shippedRevenue::varchar) AS SALES_ORDER_ITEM_ID, cast(null as varchar) AS AWB, cast(null as varchar) AS Payment_Gateway, cast(null as varchar) AS Payment_Mode, cast(null as varchar) AS COURIER, cast(null as datetime) AS DISPATCH_DATE, cast(startTime::timestamp as datetime) AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, cast(null as bigint) AS RETURN_FLAG, cast(Customer_Returns as double precision) AS returned_quantity, cast(null as double precision) AS returned_sales, cast(null as bigint) AS cancelled_quantity, cast(NULL as varchar) AS NEW_CUSTOMER_FLAG, cast(NULL as varchar) AS ACQUISITION_PRODUCT, cast(null as bigint) AS Days_in_Shipment, cast(NULL as date) AS ACQUISITION_DATE, sku_code AS SKU_CODE, PRODUCT_NAME_FINAL, product_category AS PRODUCT_CATEGORY, commonsku as commonsku, cast(null as varchar) AS WAREHOUSE, null::varchar as pincode, cast(null as varchar) pickup_pincode, cast(null as varchar) Source_name, cast(null as varchar) Mapped_Source_Name, cast(null as varchar) Order_Type, endtime::timestamp as Invoice_Date, null as week_type ,null as refund_date_final ,null as refund_value ,null as cancelled_at FROM public.ANVESHAN_AMAZON_VENDOR_PARTNER_FACT_ITEMS UNION ALL select cast(NULL AS varchar) customer_id, \'ZEPTO\' AS Shop_name, \'ZEPTO\' AS marketplace, \'ZEPTO\' AS CHANNEL, \'ZEPTO\' AS SOURCE, order_item as ORDER_ID, order_item AS reference_code, cast(null as varchar) tags, cast(NULL AS varchar) AS PHONE, cast(NULL AS varchar) as NAME, cast(NULL AS varchar) AS EMAIL, order_date AS SHIPPING_LAST_UPDATE_DATE, Sku_number as SKU, cast(SKU_NUMBER as varchar) PRODUCT_ID, Product_Name, \'INR\' as CURRENCY, City AS CITY, NUll::varchar AS STATE, \'COMPLETED\' AS Order_Status, cast(Order_Date as date) as Order_Date, CAST(Order_Date AS datetime) Order_Time, quantity, coalesce(selling_price, 0) AS GROSS_SALES_BEFORE_TAX, cast(0 as double precision) AS DISCOUNT, cast(0 as double precision) as TAX, cast(0 as double precision) as SHIPPING_PRICE, selling_price AS SELLING_PRICE, cast(null as varchar) AS OMS_order_status, \'COMPLETED\' AS SHIPPING_STATUS, \'COMPLETED\' AS FINAL_SHIPPING_STATUS, order_item AS SALEORDERITEMCODE, order_item AS SALES_ORDER_ITEM_ID, cast(null as varchar) AS AWB, cast(null as varchar) AS Payment_Gateway, cast(null as varchar) AS Payment_Mode, cast(null as varchar) AS COURIER, cast(null as datetime) AS DISPATCH_DATE, cast(order_date as datetime) AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, cast(null as bigint) AS RETURN_FLAG, cast(null as double precision) AS returned_quantity, cast(null as double precision) AS returned_sales, cast(null as bigint) AS cancelled_quantity, cast(NULL as varchar) AS NEW_CUSTOMER_FLAG, cast(NULL as varchar) AS ACQUISITION_PRODUCT, cast(null as bigint) AS Days_in_Shipment, cast(NULL as date) AS ACQUISITION_DATE, commonsku AS SKU_CODE, PRODUCT_NAME_FINAL, product_category AS PRODUCT_CATEGORY, commonsku as commonsku, cast(null as varchar) AS WAREHOUSE, null::varchar as pincode, cast(null as varchar) pickup_pincode, cast(null as varchar) Source_name, cast(null as varchar) Mapped_Source_Name, cast(null as varchar) Order_Type, Order_Date as Invoice_Date, null as week_type ,null as refund_date_final ,null as refund_value ,null as cancelled_at FROM public.anveshan_zepto_sales_fact_items zfi UNION ALL SELECT NULL::VARCHAR(256) AS customer_id, \'BLINKIT\' AS SHOP_NAME, \'BLINKIT\' AS marketplace, \'BLINKIT\' AS CHANNEL, \'BLINKIT\' AS SOURCE, bfi.order_id AS ORDER_ID, bfi.order_id AS reference_code, NULL::VARCHAR(256) AS tags, NULL::VARCHAR(256) AS PHONE, NULL::VARCHAR(256) AS NAME, NULL::VARCHAR(256) AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, bfi.commonsku AS SKU, bfi.product_id AS PRODUCT_ID, UPPER(bfi.product_name) AS PRODUCT_NAME, \'INR\' AS CURRENCY, UPPER(bfi.city) AS CITY, NULL::VARCHAR(256) AS State, \'DELIVERED\' AS ORDER_STATUS, bfi.order_date AS Order_Date, CAST(bfi.order_date AS TIMESTAMP) AS Order_Time, bfi.quantity AS QUANTITY, (bfi.Selling_Price_final * bfi.quantity) - (bfi.Selling_Price_final * bfi.quantity * COALESCE(bfi.pm_tax_Rate,0) / (100 + COALESCE(bfi.pm_tax_Rate,0))) AS GROSS_SALES_BEFORE_TAX, 0 AS DISCOUNT, (bfi.Selling_Price_final * bfi.quantity * COALESCE(bfi.pm_tax_Rate,0) / (100 + COALESCE(bfi.pm_tax_Rate,0))) AS TAX, 0 AS SHIPPING_PRICE, (bfi.Selling_Price_final * bfi.quantity) AS SELLING_PRICE, \'DELIVERED\' AS OMS_order_status, \'DELIVERED\' AS SHIPPING_STATUS, \'DELIVERED\' AS FINAL_SHIPPING_STATUS, bfi.order_id AS SALEORDERITEMCODE, bfi.order_id AS SALES_ORDER_ITEM_ID, NULL::VARCHAR(256) AS AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, NULL::VARCHAR(256) AS payment_mode, NULL::VARCHAR(256) AS COURIER, bfi.order_date AS DISPATCH_DATE, bfi.order_date AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, 0 AS RETURN_FLAG, NULL::BIGINT AS returned_quantity, NULL::NUMERIC AS returned_sales, NULL::BIGINT AS cancelled_quantity, NULL::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS acquisition_product, 0 AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, bfi.commonsku AS SKU_CODE, UPPER(bfi.Product_name_final) AS PRODUCT_NAME_FINAL, UPPER(bfi.product_category) AS PRODUCT_CATEGORY, bfi.commonsku AS commonsku, NULL::VARCHAR(256) AS WAREHOUSE, NULL::VARCHAR(20) AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, \'B2B\' AS Order_Type, NULL::DATE AS invoice_date, CASE WHEN DATEDIFF(day, bfi.order_date, DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 0 AND 6 THEN \'T-7\' WHEN DATEDIFF(day, bfi.order_date, DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 7 AND 29 THEN \'T-7-30\' WHEN DATEDIFF(day, bfi.order_date, DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 30 AND 44 THEN \'T-7-30-15\' END AS week_type, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at FROM public.anveshan_Blinkit_sales_Fact_items bfi WHERE bfi.Selling_Price_final IS NOT NULL AND bfi.quantity > 0 UNION ALL SELECT ffi.customer_id AS customer_id, UPPER(ffi.shop_name) AS SHOP_NAME, \'FLIPKART\'AS marketplace, \'FLIPKART\' AS CHANNEL, \'FLIPKART\' AS SOURCE, ffi.\"order id\" AS ORDER_ID, ffi.order_name AS reference_code, ffi.tags AS tags, ffi.phone AS PHONE, ffi.name AS NAME, ffi.email AS EMAIL, COALESCE( CAST(ffi.order_service_completion_date AS TIMESTAMP), CAST(ffi.delivery_date AS TIMESTAMP), CAST(ffi.dispatch_date AS TIMESTAMP) ) AS SHIPPING_LAST_UPDATE_DATE, ffi.SKU AS SKU, ffi.product_id AS PRODUCT_ID, UPPER(ffi.PRODUCT_NAME) AS PRODUCT_NAME, \'INR\' AS CURRENCY, UPPER(ffi.city) AS CITY, UPPER(ffi.state) AS State, UPPER(CASE WHEN ffi.cancellation_date IS NOT NULL THEN \'CANCELLED\' WHEN ffi.return_id IS NOT NULL THEN \'RETURNED\' WHEN ffi.delivery_date IS NOT NULL THEN \'DELIVERED\' WHEN ffi.dispatch_date IS NOT NULL THEN \'SHIPPED\' ELSE ffi.order_item_status END) AS ORDER_STATUS, CAST(ffi.order_date AS DATE) AS Order_Date, CAST(ffi.order_date AS TIMESTAMP) AS Order_Time, ffi.quantity AS QUANTITY, ffi.gross_sales_before_tax AS GROSS_SALES_BEFORE_TAX, ffi.discount_before_tax AS DISCOUNT, ffi.tax AS TAX, ffi.shipping_price AS SHIPPING_PRICE, ffi.total_sales AS SELLING_PRICE, UPPER(ffi.order_item_status) AS OMS_order_status, UPPER(CASE WHEN ffi.delivery_date IS NOT NULL THEN \'DELIVERED\' WHEN ffi.dispatch_date IS NOT NULL THEN \'IN TRANSIT\' WHEN ffi.cancellation_date IS NOT NULL THEN \'CANCELLED\' WHEN ffi.return_id IS NOT NULL THEN \'RETURNED\' ELSE ffi.order_item_status END) AS SHIPPING_STATUS, UPPER(CASE WHEN ffi.delivery_date IS NOT NULL THEN \'DELIVERED\' WHEN ffi.dispatch_date IS NOT NULL THEN \'IN TRANSIT\' WHEN ffi.cancellation_date IS NOT NULL THEN \'CANCELLED\' WHEN ffi.return_id IS NOT NULL THEN \'RETURNED\' ELSE ffi.order_item_status END) AS FINAL_SHIPPING_STATUS, ffi.line_item_id AS SALEORDERITEMCODE, ffi.line_item_id AS SALES_ORDER_ITEM_ID, NULL::VARCHAR(256) AS AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, UPPER(ffi.payment_mode) AS payment_mode, NULL::VARCHAR(256) AS COURIER, CAST(ffi.dispatch_date AS DATE) AS DISPATCH_DATE, CAST(ffi.delivery_date AS DATE) AS DELIVERED_DATE, CASE WHEN ffi.delivery_date IS NOT NULL THEN 1 ELSE 0 END AS DELIVERED_STATUS, ffi.is_refund AS RETURN_FLAG, CASE WHEN ffi.is_refund = 1 THEN CAST(ffi.quantity AS BIGINT) END AS returned_quantity, CASE WHEN ffi.is_refund = 1 THEN ffi.total_sales END AS returned_sales, CASE WHEN ffi.cancellation_date IS NOT NULL THEN CAST(ffi.quantity AS BIGINT) END AS cancelled_quantity, NULL::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS acquisition_product, CAST(CASE WHEN ffi.delivery_date IS NOT NULL THEN DATEDIFF(day, CAST(ffi.order_date AS DATE), CAST(ffi.delivery_date AS DATE)) WHEN ffi.dispatch_date IS NOT NULL THEN DATEDIFF(day, CAST(ffi.order_date AS DATE), CURRENT_DATE) END AS BIGINT) AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, ffi.SKU AS SKU_CODE, UPPER(COALESCE(ffi.PRODUCT_NAME)) AS PRODUCT_NAME_FINAL, UPPER(COALESCE(ffi.category)) AS PRODUCT_CATEGORY, commonsku AS commonsku, UPPER(ffi.\"Warehouse ID\") AS WAREHOUSE, ffi.pincode AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, \'B2C\' AS Order_Type, NULL::DATE AS invoice_date, CASE WHEN DATEDIFF(day, CAST(ffi.order_date AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 0 AND 6 THEN \'T-7\' WHEN DATEDIFF(day, CAST(ffi.order_date AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 7 AND 29 THEN \'T-7-30\' WHEN DATEDIFF(day, CAST(ffi.order_date AS DATE), DATEADD(day, -1, CAST(GETDATE() AT TIME ZONE \'Asia/Kolkata\' AS DATE))) BETWEEN 30 AND 44 THEN \'T-7-30-15\' END AS week_type, CAST(ffi.return_approval_date AS DATE) AS refund_date_final, CASE WHEN ffi.is_refund = 1 THEN ffi.total_sales END AS refund_value, ffi.cancellation_date AS cancelled_at FROM public.anveshan_flipkart_fact_items ffi UNION ALL SELECT * FROM public.anveshan_swiggy_sales_consolidated ; DROP TABLE IF EXISTS public.GS_State_ISO; CREATE TABLE public.GS_State_ISO ( state VARCHAR(256), iso_code VARCHAR(10) ); DROP TABLE IF EXISTS public.Final_customerID; CREATE TABLE public.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, email, contact_num, 19700000000 + DENSE_RANK() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, email, phone FROM public.Anveshan_sales_consolidated_intermediate_temp WHERE phone IS NOT NULL ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, COALESCE(p.maple_monk_id, pe.maple_monk_id) AS maple_monk_id FROM ( SELECT phone AS contact_num, email FROM public.Anveshan_sales_consolidated_intermediate_temp ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) LEFT JOIN ( SELECT * FROM ( SELECT * , ROW_NUMBER() OVER (PARTITION BY LOWER(email) ORDER BY 1) AS rn FROM new_phone_numbers ) sub WHERE rn = 1 ) pe ON LOWER(pe.email) = LOWER(e.email) ) b ) ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; DROP TABLE IF EXISTS public.Anveshan_sales_consolidated_intermediate; CREATE TABLE public.Anveshan_sales_consolidated_intermediate AS select s.customer_id, s.shop_name, s.marketplace, s.channel, s.source, s.order_id, s.reference_code, s.tags, s.phone, s.name, s.email, s.shipping_last_update_date, s.sku, s.product_id, s.product_name, s.currency, s.city, s.state, s.order_status, s.order_date, s.order_time, s.quantity/coalesce(child_sku_count,1) as quantity, coalesce(s.quantity,0) * coalesce(sm.child_quantity,1) as child_quantity, coalesce(s.gross_sales_before_tax,0) * coalesce(sm.child_to_parent_mrp,1) as gross_sales_before_tax, coalesce(s.discount,0) * coalesce(sm.child_to_parent_mrp,1) as discount, coalesce(s.tax,0) * coalesce(sm.child_to_parent_mrp,1) as tax, coalesce(s.shipping_price,0) * coalesce(sm.child_to_parent_mrp,1) as shipping_price, coalesce(s.selling_price,0) * coalesce(sm.child_to_parent_mrp,1) as selling_price, s.oms_order_status, s.shipping_status, s.final_shipping_status, s.saleorderitemcode, s.sales_order_item_id, s.awb, s.payment_gateway, s.payment_mode, s.courier, s.dispatch_date, s.delivered_date, s.delivered_status, s.return_flag, s.returned_quantity/coalesce(child_sku_count,1) as returned_quantity, coalesce(s.returned_sales,0) * coalesce(sm.child_to_parent_mrp,1) returned_sales, s.cancelled_quantity/coalesce(child_sku_count,1) as cancelled_quantity, s.new_customer_flag, s.acquisition_product, s.days_in_shipment, s.marketplace_acquisition_date, s.sku_code, s.product_name_final, s.product_category, s.commonsku, sm.child_sku, sm.child_category, sm.child_sub_category, s.warehouse, s.pincode, s.source_pincode, s.source_name, s.mapped_source_name, s.order_type, s.invoice_date, s.week_type, s.refund_date_final, coalesce(s.refund_value,0) * coalesce(sm.child_to_parent_mrp,1) refund_value, s.cancelled_at from public.Anveshan_sales_consolidated_intermediate_temp s left join (select master_sku, child_sku, child_category, child_sub_category, child_quantity, child_to_parent_mrp from public.anveshan_sku_master) sm on trim(lower(replace(sm.master_sku,\'\"\',\'\'))) = trim(lower(replace(s.commonsku,\'\"\',\'\'))) left join (select master_sku, count(child_sku) as child_sku_count from public.anveshan_sku_master group by 1) c on trim(lower(replace(c.master_sku,\'\"\',\'\'))) = trim(lower(replace(s.commonsku,\'\"\',\'\'))) ; DROP TABLE IF EXISTS public.anveshan_sales_consolidated_mid; CREATE TABLE public.anveshan_sales_consolidated_mid AS SELECT COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, SUM(COALESCE(quantity, 0)) OVER (PARTITION BY reference_code) AS Order_Quantity, CASE WHEN (ABS(selling_price) > 10 AND (order_type IS NULL OR NOT (order_type IN (\'Test Order\',\'Photoshoot Order\',\'Stock Transfer Order\',\'Raw Material Order\',\'Influencer Order\',\'Return Prime Order\')))) THEN \'Gross Sale Orders\' ELSE \'Gross Orders\' END AS GROSS_ORDER_TYPE, CASE WHEN m.pincode LIKE \'1%\' OR m.pincode LIKE \'2%\' THEN \'North Region\' WHEN m.pincode LIKE \'3%\' OR m.pincode LIKE \'4%\' THEN \'West Region\' WHEN m.pincode LIKE \'5%\' OR m.pincode LIKE \'6%\' THEN \'South Region\' WHEN m.pincode LIKE \'7%\' OR m.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region, iso.iso_code AS state_iso_code, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, o.* FROM public.Anveshan_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM public.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM public.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN ( SELECT * FROM public.GS_State_ISO ) iso ON LOWER(REPLACE(iso.state, \' \', \'\')) = LOWER(REPLACE(m.state, \' \', \'\')); ALTER TABLE public.anveshan_sales_consolidated_mid DROP COLUMN new_customer_flag; ALTER TABLE public.anveshan_sales_consolidated_mid DROP COLUMN acquisition_product; ALTER TABLE public.anveshan_sales_consolidated_mid ADD COLUMN new_customer_flag VARCHAR(256); ALTER TABLE public.anveshan_sales_consolidated_mid ADD COLUMN new_customer_flag_month VARCHAR(256); ALTER TABLE public.anveshan_sales_consolidated_mid ADD COLUMN acquisition_product VARCHAR(256); ALTER TABLE public.anveshan_sales_consolidated_mid ADD COLUMN acquisition_channel VARCHAR(256); ALTER TABLE public.anveshan_sales_consolidated_mid ADD COLUMN acquisition_marketplace VARCHAR(256); UPDATE public.anveshan_sales_consolidated_mid SET new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, order_date, CASE WHEN order_date = first_complete_order_date THEN \'New\' WHEN order_date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN order_date > first_complete_order_date THEN \'Repeat\' END AS flag, ROW_NUMBER() OVER ( PARTITION BY order_id, customer_id_final ORDER BY order_date ) AS rw FROM public.anveshan_sales_consolidated_mid ) AS B WHERE public.anveshan_sales_consolidated_mid.order_id = B.order_id AND public.anveshan_sales_consolidated_mid.customer_id_final = B.customer_id_final AND B.rw = 1; UPDATE public.anveshan_sales_consolidated_mid SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE public.anveshan_sales_consolidated_mid SET new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(\'month\', order_date) = DATE_TRUNC(\'month\', first_complete_order_date) THEN \'New\' WHEN DATE_TRUNC(\'month\', order_date) < DATE_TRUNC(\'month\', first_complete_order_date) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(\'month\', order_date) > DATE_TRUNC(\'month\', first_complete_order_date) THEN \'Repeat\' END AS flag, ROW_NUMBER() OVER (PARTITION BY order_id, customer_id_final ORDER BY order_date) AS rw FROM public.anveshan_sales_consolidated_mid ) AS B WHERE public.anveshan_sales_consolidated_mid.order_id = B.order_id AND public.anveshan_sales_consolidated_mid.customer_id_final = B.customer_id_final AND B.rw = 1; UPDATE public.anveshan_sales_consolidated_mid SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; DROP TABLE IF EXISTS temp_source_1; CREATE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM ( SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) != \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY ORDER_TIME) AS rw FROM public.anveshan_sales_consolidated_mid ) AS res WHERE rw = 1 ) WHERE order_date = firstOrderDate; UPDATE public.anveshan_sales_consolidated_mid SET acquisition_channel = b.channel FROM temp_source_1 AS b WHERE public.anveshan_sales_consolidated_mid.customer_id_final = b.customer_id_final; UPDATE public.anveshan_sales_consolidated_mid SET acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE public.anveshan_sales_consolidated_mid.customer_id_final = b.customer_id_final; DROP TABLE IF EXISTS temp_product_1; CREATE TEMPORARY TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE, MIN(CASE WHEN LOWER(order_status) != \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderdate, ROW_NUMBER() OVER (PARTITION BY customer_id_final ORDER BY ORDER_TIME ASC, selling_price DESC) AS rw FROM public.anveshan_sales_consolidated_mid ) res WHERE order_date = firstorderdate AND rw = 1; UPDATE public.anveshan_sales_consolidated_mid SET acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE public.anveshan_sales_consolidated_mid.customer_id_final = B.customer_id_final; UPDATE public.anveshan_sales_consolidated_mid SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\', \'ANDHRAPRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\', \'ASSAM HINDUISM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\', \'CHATTISGARH\', \'CHHATISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\', \'GUJRAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\', \'HIMANCHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\', \'KARANATAKA\', \'KARNATKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\', \'MADHYAPRADESH\', \'M. P\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\', \'MAHARASTRA\', \'MAHARASHATRA\', \'MAHASHTRA\', \'MUMBAI THANA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\', \'MEGALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\', \'ORISSA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\', \'TAMILNADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\', \'UTTER PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\', \'UTTRAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\', \'WEST BANGAL\', \'WB(KOLKATA & HOWRAH AREA)\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\', \'DADRA & NAGAR HAVELI\', \'DD\', \'DAMAN AND DIU\', \'DAMAN & DIU\', \'DADRA & NAGAR HAVELI AND DAMAN & DIU\', \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\', \'DADRA AND NAGAR HAV.\') THEN \'DADRA AND NAGAR HAVELI AND DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\', \'NEW DELHI\', \'NCR\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\', \'PONDICHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' WHEN UPPER(state) IN (\'AUCKLAND\', \'UNITED KINGDOM (+44)\', \'NON-US\', \'ZEELAND\', \'SINGAPORE\', \'BARCELONA\') THEN NULL WHEN UPPER(state) IN (\'INDIA\', \'1493\', \'BJP.TEAM211@GMAIL.COM\') THEN NULL WHEN UPPER(state) IN (\'NOT SPECIFIED\', \'\') THEN NULL ELSE state END; DROP TABLE IF EXISTS public.anveshan_sales_consolidated; CREATE TABLE public.anveshan_sales_consolidated AS SELECT customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, tags, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, ORDER_ID, reference_code, PHONE, NAME, EMAIL, SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, Order_Date, Order_Time, QUANTITY, child_quantity, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, PAYMENT_GATEWAY, payment_mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_quantity, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, SKU_CODE, PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, commonsku, child_sku, child_category, child_sub_category, WAREHOUSE, pincode, source_pincode, Source_name, Mapped_Source_Name, Order_Type, invoice_date, week_type, refund_date_final, refund_value, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, NULL::NUMERIC AS shopify_refund_value, NULL::NUMERIC AS return_tax, cancelled_at, state_iso_code FROM public.anveshan_sales_consolidated_mid UNION ALL SELECT NULL::BIGINT AS customer_id_final, NULL::DATE AS acquisition_date, NULL::DATE AS first_complete_order_date, NULL::NUMERIC AS Order_Quantity, NULL::VARCHAR(256) AS tags, region, maple_monk_id_phone, customer_id, SHOP_NAME, marketplace, CHANNEL, SOURCE, NULL::VARCHAR(256) AS ORDER_ID, NULL::VARCHAR(256) AS reference_code, NULL::VARCHAR(256) AS PHONE, NULL::VARCHAR(256) AS NAME, NULL::VARCHAR(256) AS EMAIL, NULL::TIMESTAMP AS SHIPPING_LAST_UPDATE_DATE, NULL::VARCHAR(256) AS SKU, NULL::VARCHAR(256) AS PRODUCT_ID, NULL::VARCHAR(256) AS PRODUCT_NAME, NULL::VARCHAR(256) AS CURRENCY, CITY, State, NULL::VARCHAR(256) AS ORDER_STATUS, refund_date_final AS Order_Date, NULL::TIMESTAMP AS Order_Time, NULL::NUMERIC AS QUANTITY, NULL::NUMERIC AS CHILD_QUANTITY, NULL::NUMERIC AS GROSS_SALES_BEFORE_TAX, NULL::NUMERIC AS DISCOUNT, NULL::NUMERIC AS TAX, NULL::NUMERIC AS SHIPPING_PRICE, NULL::NUMERIC AS SELLING_PRICE, NULL::VARCHAR(256) AS OMS_order_status, NULL::VARCHAR(256) AS SHIPPING_STATUS, NULL::VARCHAR(256) AS FINAL_SHIPPING_STATUS, NULL::VARCHAR(256) AS SALEORDERITEMCODE, NULL::VARCHAR(256) AS SALES_ORDER_ITEM_ID, NULL::VARCHAR(256) AS AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, NULL::VARCHAR(256) AS payment_mode, NULL::VARCHAR(256) AS COURIER, NULL::DATE AS DISPATCH_DATE, NULL::DATE AS DELIVERED_DATE, NULL::BIGINT AS DELIVERED_STATUS, NULL::BIGINT AS RETURN_FLAG, NULL::NUMERIC AS returned_quantity, NULL::NUMERIC AS returned_sales, NULL::BIGINT AS cancelled_quantity, NULL::BIGINT AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, NULL::VARCHAR(256) AS SKU_CODE, NULL::VARCHAR(256) AS PRODUCT_NAME_FINAL, NULL::VARCHAR(256) AS PRODUCT_CATEGORY, NULL::VARCHAR(256) AS commonsku, NULL::VARCHAR(256) AS child_sku, NULL::VARCHAR(256) AS child_category, NULL::VARCHAR(256) AS child_sub_category, NULL::VARCHAR(256) AS WAREHOUSE, NULL::VARCHAR(20) AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, Order_Type, NULL::DATE AS invoice_date, NULL::VARCHAR(256) AS week_type, refund_date_final, refund_value, NULL::VARCHAR(256) AS new_customer_flag, NULL::VARCHAR(256) AS new_customer_flag_month, NULL::VARCHAR(256) AS acquisition_product, NULL::VARCHAR(256) AS acquisition_channel, NULL::VARCHAR(256) AS acquisition_marketplace, refund_value AS shopify_refund_value, tax AS return_tax, NULL::TIMESTAMP AS cancelled_at, state_iso_code FROM public.anveshan_sales_consolidated_mid WHERE (LOWER(marketplace) LIKE \'%shopify%\' OR LOWER(marketplace) LIKE \'%website%\') AND COALESCE(refund_value, 0) > 0;",
                    "transaction": true
                }
            ) }}
